sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	//MSSOTIQUBE-235 - Host Header Checks
	var hostHeader = request.getHeader('Host');
    var checkHeader = new global.HSBC_Host_Header_Check();
    var hasHost = checkHeader.hasHostHeader(hostHeader);
    //urlSTARTSWITH/api/x_hsb11_hsbc_mss_o/el_inbound_event?api=api^sys_created_onBETWEENjavascript:gs.dateGenerate('2023-04-21','12:09:00')@javascript:gs.dateGenerate('2023-04-21','12:11:00');
    var queryParams = request.queryParams;

	//MSSOTIQUBE-235 - Host Header Checks 
    if (hasHost) {
        response.setStatus(403);
        response.setBody({error: 'Unauthorised Host header detected.'});
        return;
    }

    if (!queryParams) {
        response.setError(new sn_ws_err.BadRequestError('Missing Paramaters'));
        return;
    }

    if (!queryParams.type) {
        response.setError(new sn_ws_err.BadRequestError('Missing Paramater [type]. Expected value [period] or [duration]'));
        return;
    }
    if (queryParams.type[0] !== 'duration' && queryParams.type[0] !== 'period') {
        response.setError(new sn_ws_err.BadRequestError('Incorrect Paramater value for [type]. Expected value [period] or [duration]'));
        return;
    }
    if (queryParams.type[0] == 'period' && (!queryParams.start || !queryParams.end)) {
        response.setError(new sn_ws_err.BadRequestError('For type [period], missing paramater [start] or [end]'));
        return;
    }
    if (queryParams.type[0] == 'duration' && (!queryParams.end || !queryParams.dur)) {
        response.setError(new sn_ws_err.BadRequestError('For type [duration], missing paramater [start] or [length]'));
        return;
    }


    if (!queryParams.app) {
        response.setError(new sn_ws_err.BadRequestError('Missing Paramater [app]. Expected value [equities] or [custody]'));
        return;
    }
    if (queryParams.app[0] !== 'equities' && queryParams.app[0] !== 'custody') {
        response.setError(new sn_ws_err.BadRequestError('Incorrect Paramater value for [app]. Expected value [equities] or [custody]'));
        return;
    }
    if (queryParams.app[0] == 'equities') {
        var url = '/api/x_hsb11_hsbc_mss_o/el_inbound_event?';
		//for Custody, as events in sent in batches, thus Garfana dashboard would get data from staging table instead of call this to get number from transaction log table 
    } else if (queryParams.app[0] == 'custody') {
        var url = '/api/x_hsb11_mss_custod/el_custody_inbound_event/batch?api=api';
    }

    if (queryParams.type[0] == 'duration') {

        var end = queryParams.end[0];
        var dur = queryParams.dur[0];

        var start = new GlideDateTime(end);
        start.addSeconds(Math.abs(parseInt(dur) * 60) * -1);

        var ga = new GlideAggregate('syslog_transaction');
        ga.addQuery('url', url);
		//MSSOTIQUBE-416 Update the query, which was with BTEWEEN AND
		ga.addEncodedQuery("sys_created_on>=" + start + "^sys_created_on<" + end);
        ga.addAggregate('COUNT');
        ga.query();

        if (ga.next()) {
            response.setBody({
                type: queryParams.type[0],
                start: start.getValue(),
                dur: dur,
                end: end,
                count: ga.getAggregate('COUNT')

            });
        } else {
            return new sn_ws_err.NotFoundError('The resource you requested is not part of the API.');
        }
    }


    if (queryParams.type[0] == 'period') {

        var dateReg = /^\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}$/;
        if (queryParams.start[0].match(dateReg) === null) {
            new sn_ws_err.BadRequestError('Invalid Paramater [start]. Must be in format yyy-MM-dd HH:mm:ss');
            return;
        }
        if (queryParams.end[0].match(dateReg) === null) {
            new sn_ws_err.BadRequestError('Invalid Paramater [end]. Must be in format yyy-MM-dd HH:mm:ss');
            return;
        }
    }

    if (queryParams.type[0] == 'period') {

        var start = queryParams.start[0];
        var end = queryParams.end[0];

        var ga = new GlideAggregate('syslog_transaction');
        ga.addQuery('url', url);
		//MSSOTIQUBE-416 Update the query, which was with BTEWEEN AND
		ga.addEncodedQuery("sys_created_on>=" + start + "^sys_created_on<" + end);
        ga.addAggregate('COUNT');
        ga.query();

        if (ga.next()) {

            response.setBody({
                type: queryParams.type[0],
                start: start,
                end: end,
                count: ga.getAggregate('COUNT')

            });

        } else {
            return new sn_ws_err.NotFoundError('The resource you requested is not part of the API.');
        }

    }



})(request, response);
